function wbRand(n){return Math.floor(Math.random()*n);}
function wbPick(a){return a[wbRand(a.length)];}
function wbShuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=wbRand(i+1),t=a[i];a[i]=a[j];a[j]=t;}return a;}
